std::string decode_json_web_token(const std::string& token, const std::string& key) {
    // BEGIN SOLUTION
    jwt_t* jwt = nullptr;

    // Decode JWT
    int ret = jwt_decode(&jwt, token.c_str(), nullptr, 0);
    if (ret != 0) {
